const items = $input.all();
const results = [];
for (const i of items) {
  const name = i.json['наименование'];
  if (!name) continue;
  results.push({
    наименование: name,
    ед_измерения: i.json['ед_измерения'] || '',
    артикул: i.json['артикул'] || '',
    цена_оптовая: i.json['цена_оптовая'] ?? null,
    валюта: i.json['валюта'] || '',
    кол_во: i.json['кол_во'] || 1
  });
}
return [{ json: { results } }];
